import{_ as t,o as s,c as i,aO as e}from"./chunks/framework.BFrk9dwu.js";const c=JSON.parse('{"title":"工具与部署","description":"","frontmatter":{"date":"2026-11-27T11:05:18.000Z","title":"工具与部署","sidebarSort":3,"categories":["ai"],"permalink":"/pages/704655"},"headers":[],"relativePath":"ai/基础知识/工具与部署.md","filePath":"ai/基础知识/工具与部署.md"}'),n={name:"ai/基础知识/工具与部署.md"};function l(h,a,d,o,p,r){return s(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="工具与部署" tabindex="-1">工具与部署 <a class="header-anchor" href="#工具与部署" aria-label="Permalink to &quot;工具与部署&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>这一组讲「在哪里用」：网页对话、厂商 API、本地推理、自建界面。四者能力同源，差别在<strong>数据能不能出内网</strong>和<strong>要不要自动化</strong>。</p><h2 id="有什么用" tabindex="-1">有什么用 <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>该选哪种</th></tr></thead><tbody><tr><td>临时问一句、写点东西</td><td>网页对话，零成本</td></tr><tr><td>每天自动跑一批任务</td><td>API + 脚本</td></tr><tr><td>资料涉密、不能外传</td><td>本地推理</td></tr><tr><td>团队共用一个入口</td><td>自建 Web 界面</td></tr></tbody></table><h2 id="三条落地方式对比" tabindex="-1">三条落地方式对比 <a class="header-anchor" href="#三条落地方式对比" aria-label="Permalink to &quot;三条落地方式对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>上手成本</th><th>成本模型</th><th>数据流向</th></tr></thead><tbody><tr><td>网页对话</td><td>最低</td><td>订阅制</td><td>出内网</td></tr><tr><td>厂商 API</td><td>中（要写代码）</td><td>按 token 计费</td><td>出内网</td></tr><tr><td>本地推理（Ollama）</td><td>中（要装环境）</td><td>电费 + 硬件</td><td>留在本机</td></tr></tbody></table><h2 id="本地部署-ollama" tabindex="-1">本地部署：Ollama <a class="header-anchor" href="#本地部署-ollama" aria-label="Permalink to &quot;本地部署：Ollama&quot;">​</a></h2><p>最省事的本地方案，一条命令拉起服务，默认开在 <code>11434</code> 端口。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拉模型并直接对话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5:7b</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看已下载的模型、运行状态</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><p>调接口就是普通 HTTP：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:11434/api/chat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;model&quot;: &quot;qwen2.5:7b&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;messages&quot;: [{&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;用三句话解释什么是索引&quot;}],</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;stream&quot;: false</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&#39;</span></span></code></pre></div><p>要对外提供服务，加个反向代理并绑定 <code>OLLAMA_HOST=0.0.0.0:11434</code>；只在本机用就保持默认，别裸奔到公网。</p><h2 id="自建界面-open-webui" tabindex="-1">自建界面：Open WebUI <a class="header-anchor" href="#自建界面-open-webui" aria-label="Permalink to &quot;自建界面：Open WebUI&quot;">​</a></h2><p>把本地模型包成网页服务，一条 docker 命令即可，注意两点：<strong>端口映射</strong>和<strong>首次注册的账号就是管理员</strong>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-webui</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --add-host=host.docker.internal:host-gateway</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> open-webui:/app/backend/data</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> always</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ghcr.io/open-webui/open-webui:main</span></span></code></pre></div><p>容器内访问宿主机的 Ollama 用 <code>host.docker.internal</code>，不要写 <code>localhost</code>——容器里的 localhost 是容器自己。</p><h2 id="接-api-的要点" tabindex="-1">接 API 的要点 <a class="header-anchor" href="#接-api-的要点" aria-label="Permalink to &quot;接 API 的要点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要点</th><th>做法</th></tr></thead><tbody><tr><td>密钥</td><td>只从环境变量读，别写进代码和仓库</td></tr><tr><td>超时</td><td>显式设置 30–60 秒，流式接口单独放宽</td></tr><tr><td>重试</td><td>只重试 429 和 5xx，指数退避，最多 3 次</td></tr><tr><td>成本</td><td>记录每轮 token 用量，超预算先降 max_tokens</td></tr><tr><td>版本</td><td>固定模型名，别用会漂移的别名</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p><strong>现象：容器里连不上本机的 Ollama。</strong> 原因：<code>localhost</code> 在容器内指向容器自身。 解法：用 <code>host.docker.internal</code>，或在 Linux 上用宿主机内网 IP，并确认已监听 <code>0.0.0.0</code>。</p><p><strong>现象：本地模型第一次回答特别慢。</strong> 原因：首次加载权重要读盘，模型越大越明显。 解法：预热一次请求；常驻场景配 <code>restart: always</code>，别让它反复退出。</p><p><strong>现象：账单比预期高好几倍。</strong> 原因：每次请求都重发完整历史，token 按累计算。 解法：历史做摘要压缩，限制 max_tokens，长文档走检索而不是全量塞入。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ol><li>选型只看两条：数据能不能出内网、要不要自动化</li><li>本地起步用 Ollama，一条命令跑通，接口就是 HTTP</li><li>容器访问宿主机服务，用 <code>host.docker.internal</code>，不是 <code>localhost</code></li><li>接 API 必做四件事：密钥进环境变量、设超时、限定重试、记录 token</li><li>自建界面首次注册的账号即管理员，部署完立刻改密码</li></ol>`,25)])])}const F=t(n,[["render",l]]);export{c as __pageData,F as default};
